inline flight::Ref<SpritesheetFrameData> frame_from_region(flight::Ref<TextureAtlasRegion> region) {
  const bool rotated = (region->rotation != texture_atlas_rotation.none);
  const double width = (rotated ? region->height : region->width);
  const double height = (rotated ? region->width : region->height);
  return create_spritesheet_frame_data({.height = height, .name = region->name.value_or(flight::String("")), .offset_x = region->source_x, .offset_y = region->source_y, .pivot_x = region->pivot_x, .pivot_y = region->pivot_y, .rotated = rotated, .source_height = region->original_height.value_or(height), .source_width = region->original_width.value_or(width), .width = width, .x = region->x, .y = region->y});
}

